<script setup lang="ts">
import { ref } from 'vue'
import { Refresh } from '@element-plus/icons-vue'
import { api, items, query } from '../api'
import { useLoad } from '../composables'
const rows=ref<any[]>([]),page=ref(1),total=ref(0),action=ref('')
const {loading,error,load}=useLoad(async()=>{const data=await api('/audit-logs?'+query({page:page.value-1,size:20,action:action.value}));rows.value=items(data);total.value=data.total??rows.value.length})
const labels:Record<string,string>={LOGIN:'登录',LOGOUT:'退出登录',PASSWORD_CHANGE:'修改密码',EMPLOYEE_CREATE:'创建员工',EMPLOYEE_UPDATE:'更新员工',FACE_ENROLL:'录入人脸',FACE_DELETE:'删除人脸',DEVICE_CREATE:'授权设备',DEVICE_REVOKE:'撤销设备',SETTINGS_UPDATE:'修改设置',RULE_UPDATE:'修改规则',CALENDAR_UPDATE:'更新工作日历',LEAVE_REVIEW:'请假审批',CORRECTION_REVIEW:'补卡审批',GALLERY_SYNC:'人员库同步'}
Object.assign(labels, { UPDATE_ATTENDANCE_POLICY: '修改考勤方式', CREATE_ATTENDANCE_LOCATION: '添加考勤地点', UPDATE_ATTENDANCE_LOCATION: '更新考勤地点', DELETE_ATTENDANCE_LOCATION: '删除考勤地点', LOCATION_PUNCH: '员工定位打卡', CREATE_LEAVE: '提交请假', CANCEL_LEAVE: '撤销请假', REVIEW_LEAVE: '审批请假', CREATE_CORRECTION: '提交补卡', CANCEL_CORRECTION: '撤销补卡', REVIEW_CORRECTION: '审批补卡' })
function detail(value:any){return typeof value==='string'?value:value?JSON.stringify(value):'—'}
</script>
<template><div class="page-head"><div><h1>操作日志</h1></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新日志</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="action" placeholder="操作类型，例如 ENROLL_FACE" style="width:320px" clearable @keyup.enter="page=1;load()"/><el-button type="primary" @click="page=1;load()">查询</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" empty-text="当前条件下暂无操作日志"><el-table-column prop="createdAt" label="操作时间" width="190"/><el-table-column label="操作人" min-width="120"><template #default="{row}">{{row.actorName||row.username||row.actor||'系统'}}</template></el-table-column><el-table-column label="操作" min-width="150"><template #default="{row}">{{labels[row.action]||row.action}}</template></el-table-column><el-table-column label="操作对象" min-width="150"><template #default="{row}">{{row.target||row.targetType||row.entityType||'—'}}{{row.targetId?' #'+row.targetId:''}}</template></el-table-column><el-table-column label="说明" min-width="240" show-overflow-tooltip><template #default="{row}">{{detail(row.detail||row.details||row.changes)}}</template></el-table-column><el-table-column prop="requestId" label="请求编号" min-width="200" show-overflow-tooltip/></el-table><div class="pagination"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></div></div></template>
